// We use the Verus verifier to prove that `min` indeed returns
// one of its two inputs and that this returned value is less than
// or equal to both inputs.

verus! {

    /// Returns the minimum of two mathematical integers `a` and `b`.
    /// Ensures:
    ///   1. `result <= a`
    ///   2. `result <= b`
    ///   3. `result == a || result == b`  (we only return one of the two inputs)
    fn min(a: int, b: int) -> (result: int)
        ensures
            result <= a,
            result <= b,
            result == a || result == b
    {
        if a <= b {
            // If a is at most b, then a is the minimum.
            result = a;
            // Supporting assertions help Verus close the proof obligations.
            assert(result == a);
            assert(result <= b); // since a <= b
        } else {
            // Otherwise b < a, so b is the minimum.
            result = b;
            assert(result == b);
            assert(result <= a); // since b < a
        }
    }

    #[verifier::proof]
    impl proof_min {
        /// A small proof that `min` behaves correctly on some examples.
        /// This can be used to exercise the verifier.
        proof fn test_min_cases() {
            // Case: a < b
            assert(min(3, 5) == 3);
            // Case: a == b
            assert(min(7, 7) == 7);
            // Case: a > b
            assert(min(10, 2) == 2);
        }
    }
}